(()=>{const page=document.querySelector('[data-provider-reconciliation-page]');if(!page)return;const summary=page.querySelector('[data-summary]'),transfers=page.querySelector('[data-transfer-list]'),events=page.querySelector('[data-event-list]');const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));const money=(c,cur)=>new Intl.NumberFormat(undefined,{style:'currency',currency:cur||'USD'}).format((Number(c)||0)/100);async function load(){summary.textContent='Loading…';const r=await fetch('/api/admin/bundle-provider-reconciliation.php',{credentials:'same-origin',headers:{Accept:'application/json'}});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Unable to load reconciliation data.');const d=j.data||j;summary.innerHTML=`<strong>Mode: ${esc(d.payment_mode)}</strong><span>Dispatch ${d.dispatch_enabled?'enabled':'disabled'}</span><span>Live ${d.live_dispatch_enabled?'enabled':'disabled'}</span>`;transfers.innerHTML=(d.items||[]).map(x=>`<article><div><strong>${esc(x.merchant_name)}</strong><span>${esc(x.transfer_status)} · ${money(x.amount_cents,x.currency)}</span><small>${esc(x.provider_transfer_reference||'Not dispatched')}</small></div>${x.provider_transfer_reference?`<button type="button" data-reconcile="${esc(x.public_id)}">Reconcile</button>`:''}</article>`).join('')||'<p>No transfers.</p>';events.innerHTML=(d.events||[]).map(x=>`<article><strong>${esc(x.event_type)}</strong><span>${esc(x.processing_status)}</span><small>${esc(x.provider_transfer_reference||x.provider_event_reference)}</small></article>`).join('')||'<p>No provider events.</p>';}async function reconcile(id){const token=document.querySelector('meta[name="csrf-token"]')?.content||window.MG_CSRF_TOKEN||'';const body=new URLSearchParams({action:'reconcile',transfer_id:id,csrf_token:token});const r=await fetch('/api/admin/bundle-provider-reconciliation.php',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded'},body});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Reconciliation failed.');await load();}page.addEventListener('click',e=>{const b=e.target.closest('[data-refresh],[data-reconcile]');if(!b)return;b.disabled=true;(b.dataset.reconcile?reconcile(b.dataset.reconcile):load()).catch(err=>alert(err.message)).finally(()=>b.disabled=false);});load().catch(err=>{summary.textContent=err.message;});})();
